<?php
require_once "../db.php";requireAdmin();$repo=new SpaceRepository($pdo);$error="";
if($_SERVER["REQUEST_METHOD"]==="POST"){$n=trim($_POST["name"]??"");$c=filter_input(INPUT_POST,"capacity",FILTER_VALIDATE_INT);$p=filter_input(INPUT_POST,"price",FILTER_VALIDATE_FLOAT);$d=trim($_POST["description"]??"");if($n===""||!$c||$c<1||$p===false||$p<0)$error="Enter valid space details.";else{$repo->create($n,$c,$p,$d);header("Location: spaces.php?added=1");exit;}}
$rows=$repo->getAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Spaces | CoworkSpace Admin</title><link rel="stylesheet" href="../assets/style.css"></head><body><header class="navbar"><div class="container nav-content"><a class="logo" href="index.php">Cowork<span>Admin</span></a><nav class="nav-links"><a href="index.php">Dashboard</a><a class="active" href="spaces.php">Spaces</a><a href="time-slots.php">Time slots</a><a href="users.php">Users</a><a href="../logout.php">Log out</a></nav></div></header><main class="section"><div class="container"><div class="section-heading"><div><span class="eyebrow">WORKSPACES</span><h1>Manage spaces</h1></div><a class="btn btn-outline" href="index.php">Back to dashboard</a></div><?php if($error):?><div class="alert error"><?=htmlspecialchars($error)?></div><?php endif;?><?php if(isset($_GET["added"])):?><div class="alert success">Space added.</div><?php endif;?><?php if(isset($_GET["delete_error"])):?><div class="alert error">Spaces with time slots or reservations cannot be deleted.</div><?php endif;?><div class="admin-grid"><section class="panel"><h2>Add a space</h2><form method="POST"><div class="form-group"><label>Name</label><input name="name" maxlength="100" required></div><div class="form-group"><label>Maximum capacity</label><input type="number" name="capacity" min="1" required></div><div class="form-group"><label>Price per hour (JOD)</label><input type="number" name="price" step=".01" min="0" required></div><div class="form-group"><label>Description</label><textarea name="description" rows="3"></textarea></div><button class="btn">Add space</button></form></section><section class="panel"><h2>Current spaces</h2><?php if(!$rows):?><p class="muted">No spaces yet.</p><?php else:?><div class="table-wrapper"><table><thead><tr><th>Name</th><th>Capacity</th><th>Price</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $s):?><tr><td><?=htmlspecialchars($s["name"])?></td><td><?=(int)$s["capacity"]?></td><td><?=htmlspecialchars($s["price"])?></td><td class="actions"><a class="btn btn-small btn-outline" href="edit-space.php?id=<?=(int)$s["id"]?>">Edit</a><form method="POST" action="delete-space.php" onsubmit="return confirm('Delete this space?')"><input type="hidden" name="id" value="<?=(int)$s["id"]?>"><button class="btn btn-small btn-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></div></div></main><footer class="footer"><div class="container">CoworkSpace Admin</div></footer></body></html>
